def get_players(roles=None):
    if roles is None:
        roles = var.ROLES

    players = set()
    for x in roles:
        if x in var.TEMPLATE_RESTRICTIONS:
            continue
        for p in var.ROLES.get(x, ()):
            players.add(p)

    return [p for p in var.ALL_PLAYERS if p.nick in players]

